const icons={search:'<circle cx="10.5" cy="10.5" r="6.8"/><path d="m16 16 5 5"/>',heart:'<path d="M20.8 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.5a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3Z"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};
const svg=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[k]}</svg>`;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let lang=/^\/(fr|en|ar)(\/|$)/.exec(location.pathname)?.[1]||read('lm-language','fr');if(!dictionaries[lang])lang='fr';
let route=location.pathname.replace(/^\/(fr|en|ar)/,'')||'/',cart=read('lm-cart',[]),wish=read('lm-wish',[]),variants=read('lm-variants',{}),slide=0,filter=new URLSearchParams(location.search).get('category')||'',query='',sort='best',maxPrice=500,filterSize='',overlay='',formDraft={};
const t=k=>dictionaries[lang][k],idx=()=>['fr','en','ar'].indexOf(lang),name=p=>p.name[idx()],category=c=>c[1][idx()],money=n=>new Intl.NumberFormat(lang==='ar'?'ar-MA':lang==='fr'?'fr-MA':'en-MA',{style:'currency',currency:'MAD',maximumFractionDigits:0}).format(n),asset=k=>`/assets/${k}.png`,url=p=>`/${lang}${p==='/'?'':p}`,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem('lm-cart',JSON.stringify(cart));localStorage.setItem('lm-wish',JSON.stringify(wish));localStorage.setItem('lm-variants',JSON.stringify(variants));localStorage.setItem('lm-language',JSON.stringify(lang))}
const link=(p,label,cls='')=>`<a href="${url(p)}" data-route="${p}" class="${cls}">${label}</a>`;
const arrow='<span class="arrow">→</span>';
const btn=(p,label,cls='')=>link(p,`${label}${arrow}`,`btn ${cls}`);
function langs(){return `<div class="lang" role="group" aria-label="${t('language')}">${['fr','en','ar'].map(l=>`<button data-lang="${l}" aria-pressed="${l===lang}">${l.toUpperCase()}</button>`).join('<span aria-hidden="true">|</span>')}</div>`}
function header(){return `<div class="announcement"><span>${link('/shipping',t('shipping'))}${link('/shipping',t('cod'))}${link('/shipping',t('returns'))}</span><span>${link('/contact',t('help'))}</span></div><header class="header"><div class="wrap nav"><button class="mobile icon" data-action="menu" aria-label="${t('menu')}">${svg('menu')}</button>${link('/',`<img src="${asset('logo')}" alt="L&M"><small>CONFORT</small>`,'logo')}<nav class="links">${['home','sale','shop','categories','about','contact'].map((k,i)=>link(['/','/sale','/shop','/categories','/about','/contact'][i],t(k),route===['/','/sale','/shop','/categories','/about','/contact'][i]?'active':'')).join('')}</nav><div class="tools">${langs()}<button class="icon" data-action="search" aria-label="${t('search')}">${svg('search')}</button>${link('/account',svg('user'),'icon account')}${link('/wishlist',svg('heart')+(wish.length?`<span class="count">${wish.length}</span>`:''),'icon')}<button class="icon" data-action="cart" aria-label="${t('cart')}">${svg('bag')}${cart.length?`<span class="count">${cart.reduce((n,c)=>n+c.qty,0)}</span>`:''}</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div>${link('/',`<img src="${asset('logo')}" alt="L&M Confort" style="width:120px">`)}<p>${t('heroDesc')}</p></div><div><h4>${t('quickLinks')}</h4>${link('/',t('home'))}${link('/shop',t('shop'))}${link('/sale',t('sale'))}${link('/categories',t('categories'))}</div><div><h4>${t('service')}</h4>${link('/contact',t('contact'))}${link('/shipping',t('policies'))}${link('/privacy',t('privacy'))}${link('/terms',t('terms'))}</div><div><h4>${t('newsletter')}</h4><p>${t('newsletterDesc')}</p><form class="newsletter" data-form="newsletter"><input type="email" required aria-label="${t('email')}" placeholder="${t('email')}"><button aria-label="${t('subscribe')}">→</button></form><p>${t('newsletterNote')}</p></div></div><div class="copyright"><span>© ${new Date().getFullYear()} L&M Confort. ${t('rights')}</span><span>${t('shipping')} · ${t('cod')}</span></div></div></footer>`}
function card(p){return `<article class="product"><div class="product-image">${link('/product/'+p.id,`<img src="${asset(p.image)}" alt="${name(p)}" loading="lazy" width="400" height="400">`)}<button class="heart icon ${wish.includes(p.id)?'saved':''}" data-wish="${p.id}" aria-label="${t('wishlist')}: ${name(p)}" aria-pressed="${wish.includes(p.id)}">${svg('heart')}</button>${link('/product/'+p.id,t('quick'),'quick')}</div>${link('/product/'+p.id,`<h3>${name(p)}</h3>`)}<bdi class="price">${money(p.price)}</bdi><div class="swatch" title="${t(p.image==='boots'||p.image==='flats'?'black':'blush')}"></div></article>`}
const grid=(items,cls='')=>`<div class="products ${cls}">${items.map(card).join('')}</div>`;
function home(){let images=['hero-wide','campaign','brand'];return `<section class="hero ${slide===0?"hero-reference":""}"><img class="hero-photo" src="${asset(images[slide])}" alt="L&M Confort" fetchpriority="high"><div class="wrap"><div class="hero-content"><div class="eyebrow">${t('newCollection')}</div><h1>${t('hero1')}<em>${t('hero2')}</em></h1><p>${t('heroDesc')}</p>${btn('/shop',t('discover'))}</div><div class="slider"><button data-slide="${(slide+2)%3}" aria-label="${t('previous')}">←</button>${[0,1,2].map(n=>`<button data-slide="${n}" class="${n===slide?'active':''}" aria-label="${n+1}" aria-pressed="${n===slide}">0${n+1}</button>`).join('')}<button data-slide="${(slide+1)%3}" aria-label="${t('next')}">→</button></div></div></section><div class="wrap"><section class="section"><div class="section-head"><h2>${t('ourCategories')}</h2>${link('/categories',t('allCategories')+arrow,'text-link')}</div>${categoryGrid()}</section><section class="promo"><img src="${asset('campaign')}" alt="" loading="lazy"><div class="banner-copy"><div class="eyebrow">${t('soft')}</div><h2>${t('sale')}</h2><p>${t('saleDesc')}</p>${btn('/sale',t('selection'),'light')}</div></section><section class="section"><div class="section-head"><h2>${t('bestsellers')}</h2>${link('/shop',t('allProducts')+arrow,'text-link')}</div>${grid(products)}</section></div><section class="editorial full"><img src="${asset('story')}" alt="" loading="lazy"><div class="wrap"><div class="banner-copy"><h2>L&M Confort</h2><h3>${t('art')}</h3><p>${t('storyDesc')}</p>${btn('/about',t('story'))}</div></div></section><div class="wrap"><section class="section"><div class="section-head"><h2>${t('brands')}</h2></div><div class="editorial"><img src="${asset('brand')}" alt="" loading="lazy"><div class="banner-copy"><h2>L&M Confort</h2><h3>${t('exclusive')}</h3><p>${t('brandDesc')}</p>${btn('/shop',t('brandCta'),'light')}</div></div></section><section class="instagram"><div><h3>${t('instagram')}</h3><p>${t('instaDesc')}</p></div>${['campaign','bags','sneakers','sandals','loafers','evening'].map(k=>`<button data-gallery="${k}" aria-label="${t('gallery')}"><img src="${asset(k)}" alt="${category(cats.find(c=>c[0]===k)||cats[0])}" loading="lazy"></button>`).join('')}</section></div>`}
function categoryGrid(){return `<div class="categories">${cats.map(c=>link('/shop?category='+c[0],`<img src="${asset(c[0])}" alt="${category(c)}" loading="lazy"><h3>${category(c)}</h3>`,'category')).join('')}</div>`}
function empty(kind){return `<div class="empty"><h2>${t(kind)}</h2><p>${t('emptyDesc')}</p>${btn('/shop',t('discover'))}</div>`}
function catalog(){let list=products.filter(p=>(!filter||p.cat===filter)&&p.price<=maxPrice&&name(p).toLocaleLowerCase().includes(query.toLocaleLowerCase()));if(sort==='asc')list.sort((a,b)=>a.price-b.price);if(sort==='desc')list.sort((a,b)=>b.price-a.price);if(sort==='newest')list.reverse();return `<h1 class="page-title">${t(route==='/sale'?'sale':'shop')}</h1>${route==='/sale'?`<p class="note">${t('saleNote')}</p>`:''}<div class="chips"><button class="chip ${!filter?'active':''}" data-filter="">${t('all')}</button>${cats.map(c=>`<button class="chip ${filter===c[0]?'active':''}" data-filter="${c[0]}">${category(c)}</button>`).join('')}</div><div class="toolbar"><input id="catalog-search" type="search" value="${esc(query)}" placeholder="${t('searchPlaceholder')}" aria-label="${t('search')}"><select id="sort" aria-label="${t('sort')}">${['best','newest','asc','desc'].map(k=>`<option value="${k}" ${sort===k?'selected':''}>${t(k)}</option>`).join('')}</select><label>${t('priceMax')} <input id="price" type="range" min="250" max="500" step="1" value="${maxPrice}" aria-label="${t('priceMax')}"> <bdi>${money(maxPrice)}</bdi></label><button class="chip" data-action="reset">${t('reset')}</button></div><p style="margin-bottom:20px;color:var(--muted);font-size:12px">${list.length} ${t('results')}</p>${list.length?grid(list,'catalog'):empty('noResults')}`}
function detail(id){let p=products.find(p=>p.id===id);if(!p)return empty('noResults');let v=variants[id]||{};return `<div class="breadcrumb">${link('/shop',t('shop'))} <span class="arrow">/</span> ${name(p)}</div><div class="detail"><div class="detail-image"><button data-gallery="${p.image}" aria-label="${t('zoom')}" style="padding:0;width:100%"><img id="main-product" src="${asset(p.image)}" alt="${name(p)}"></button>${p.alt?`<div class="thumbs">${[p.image,p.alt].map(k=>`<button data-thumb="${k}" aria-label="${t('gallery')}"><img src="${asset(k)}" alt="${name(p)}"></button>`).join('')}</div>`:''}</div><div class="detail-info"><div class="eyebrow">L&M CONFORT</div><h1>${name(p)}</h1><bdi class="price">${money(p.price)}</bdi><p>${t('productDesc')}</p><span class="label">${t('color')} : ${t(p.image==='boots'||p.image==='flats'?'black':'blush')}</span><div class="swatch"></div><span class="label">${t('size')}</span><div class="sizes">${[36,37,38,39,40,41].map(n=>`<button class="size ${v.size===n?'active':''}" data-size="${n}" data-product="${id}" aria-pressed="${v.size===n}">${n}</button>`).join('')}</div><label class="label">${t('quantity')} <input id="product-qty" type="number" min="1" max="10" value="${v.qty||1}" style="width:75px;margin-inline-start:12px"></label><div class="detail-actions"><button class="btn" data-add="${id}">${t('add')}${arrow}</button><button class="icon" data-wish="${id}" aria-label="${t('wishlist')}">${svg('heart')}</button></div>${['details','guide','delivery'].map((k,i)=>`<details ${i===0?'open':''}><summary>${t(k)}</summary><p>${t(['specs','guideText','deliveryText'][i])}</p>${i===2?`<p>${t('returnText')}</p>`:''}</details>`).join('')}</div></div><section class="section"><h2 style="margin-bottom:25px">${t('related')}</h2>${grid(products.filter(q=>q.id!==id).slice(0,3))}</section>`}
function cartRows(){return cart.map((c,i)=>{let p=products.find(p=>p.id===c.id);return `<div class="cart-row"><img src="${asset(p.image)}" alt="${name(p)}"><div class="row-info">${link('/product/'+p.id,`<h3>${name(p)}</h3>`)}<small>${t('size')}: <bdi>${c.size}</bdi> · ${t(p.image==='boots'||p.image==='flats'?'black':'blush')}</small><br><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="− ${t('quantity')}">−</button><span>${c.qty}</span><button data-qty="${i}" data-delta="1" aria-label="+ ${t('quantity')}">+</button></div> <button data-remove="${i}" style="font-size:10px;text-decoration:underline">${t('remove')}</button></div><bdi class="price">${money(p.price*c.qty)}</bdi></div>`}).join('')}
const subtotal=()=>cart.reduce((n,c)=>n+products.find(p=>p.id===c.id).price*c.qty,0);
function cartContent(drawer=false){return cart.length?`${cartRows()}<div class="total"><span>${t('subtotal')}</span><bdi>${money(subtotal())}</bdi></div><p class="note">${t('deliveryText')}</p>${btn('/checkout',t('checkout'))} ${btn(drawer?'/cart':'/shop',t(drawer?'viewCart':'continue'),'outline')}`:empty('emptyCart')}
function checkout(){return `<h1 class="page-title">${t('checkout')}</h1>${!cart.length?empty('emptyCart'):`<div class="checkout-grid"><form data-form="checkout"><h3>${t('delivery')}</h3><div class="form-grid">${['first','last','phone','email','city','address','notes'].map(k=>`<label class="${['address','notes'].includes(k)?'wide':''}">${t(k)}${k==='notes'?`<textarea name="${k}" rows="3">${esc(formDraft[k]||'')}</textarea>`:`<input name="${k}" type="${k==='email'?'email':k==='phone'?'tel':'text'}" value="${esc(formDraft[k]||'')}" required autocomplete="${({first:'given-name',last:'family-name',phone:'tel',email:'email',city:'address-level2',address:'street-address'})[k]}" ${['email','phone'].includes(k)?'dir="ltr"':''}>`}</label>`).join('')}</div><div class="note"><b>${t('payment')}</b><br>${t('cod')}</div><p class="note">${t('demo')}</p><button class="btn">${t('review')}${arrow}</button></form><div><h3>${t('summary')}</h3>${cartRows()}<div class="total"><span>${t('subtotal')}</span><bdi>${money(subtotal())}</bdi></div><p class="note">${t('deliveryText')}</p></div></div>`}`}
function info(){const key=route.slice(1);if(key==='account')return `<div class="prose"><h1 class="page-title">${t('accountTitle')}</h1><p>${t('accountDesc')}</p>${btn('/wishlist',t('wishlist'))}</div>`;if(key==='contact')return `<div class="checkout-grid"><div class="prose"><h1 class="page-title">${t('contactTitle')}</h1><p>${t('contactDesc')}</p><p class="note">${t('contactNote')}</p></div><form data-form="contact" class="form-grid"><label>${t('first')}<input required name="first"></label><label>${t('email')}<input required type="email" name="email"></label><label class="wide">${t('message')}<textarea required rows="6" name="message"></textarea></label><button class="btn">${t('previewMessage')}${arrow}</button></form></div>`;return `<div class="prose"><h1 class="page-title">${t(({about:'story',shipping:'policies',privacy:'privacy',terms:'terms'})[key]||'about')}</h1>${key==='about'?`<img src="${asset('story')}" alt="L&M Confort"><h2 style="margin-top:30px">${t('art')}</h2><p>${t('storyDesc')}</p><p>${t('brandDesc')}</p>${btn('/shop',t('discover'))}`:key==='shipping'?`<p>${t('deliveryText')}</p><p>${t('returnText')}</p>`:`<p>${t(key==='privacy'?'privacyText':'termsText')}</p>`}</div>`}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';save();let title=route.startsWith('/product/')?name(products.find(p=>p.id===route.split('/')[2])||products[0]):t(({'/':'home','/shop':'shop','/sale':'sale','/cart':'cart','/wishlist':'wishlist','/checkout':'checkout','/categories':'categories','/account':'account','/about':'about','/contact':'contact','/shipping':'policies','/privacy':'privacy','/terms':'terms'})[route]||'home');document.title=title+' | L&M Confort';document.querySelector('meta[name="description"]').content=t('heroDesc');document.querySelectorAll('link[hreflang],link[rel="canonical"]').forEach(e=>e.remove());for(let l of ['fr','en','ar','x-default']){let a=document.createElement('link');a.rel='alternate';a.hreflang=l;a.href=location.origin+'/'+(l==='x-default'?'fr':l)+(route==='/'?'':route);document.head.append(a)}let canonical=document.createElement('link');canonical.rel='canonical';canonical.href=location.origin+url(route);document.head.append(canonical);let body=route==='/'?home():`<div class="wrap page">${route==='/shop'||route==='/sale'?catalog():route==='/categories'?`<h1 class="page-title">${t('ourCategories')}</h1>${categoryGrid()}`:route.startsWith('/product/')?detail(route.split('/')[2]):route==='/cart'?`<h1 class="page-title">${t('cart')}</h1>${cartContent()}`:route==='/wishlist'?`<h1 class="page-title">${t('wishlist')}</h1>${wish.length?grid(products.filter(p=>wish.includes(p.id)),'catalog'):empty('emptyWishlist')}`:route==='/checkout'?checkout():info()}</div>`;document.getElementById('app').innerHTML=header()+`<main>${body}</main>`+footer();renderOverlay()}
function navigate(path){let u=new URL(path,location.origin);route=u.pathname;filter=u.searchParams.get('category')||'';query='';history.pushState({},'',url(route)+u.search);overlay='';render();scrollTo({top:0,behavior:'instant'})}
function renderOverlay(){let el=document.getElementById('overlay');document.body.style.overflow=overlay?'hidden':'';if(!overlay){el.innerHTML='';return}let close=`<button class="close" data-action="close" aria-label="${t('close')}">×</button>`;if(overlay==='search'){el.innerHTML=`<div class="backdrop" data-action="close"></div><section class="search-panel" role="dialog" aria-modal="true" aria-label="${t('search')}"><div class="drawer-head"><h2>${t('search')}</h2>${close}</div><input id="global-search" type="search" placeholder="${t('searchPlaceholder')}" aria-label="${t('search')}"><div id="search-results">${grid(products.slice(0,3))}</div></section>`;setTimeout(()=>document.getElementById('global-search')?.focus(),0);return}let body=overlay==='cart'?cartContent(true):overlay==='menu'?`<nav>${['home','shop','sale','categories','about','contact','account','wishlist'].map((k,i)=>link(['/','/shop','/sale','/categories','/about','/contact','/account','/wishlist'][i],t(k))).join('')}</nav>${langs()}`:`<img src="${asset(overlay.slice(8))}" alt="${t('gallery')}">`;el.innerHTML=`<div class="backdrop" data-action="close"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="${t(overlay==='cart'?'cart':overlay==='menu'?'menu':'gallery')}"><div class="drawer-head"><h2>${t(overlay==='cart'?'cart':overlay==='menu'?'menu':'gallery')}</h2>${close}</div>${body}</aside>`;setTimeout(()=>el.querySelector('.close')?.focus(),0)}
function toast(message){let e=document.getElementById('toast');e.textContent=message;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3500)}
document.addEventListener('click',e=>{let a=e.target.closest('[data-route]');if(a){e.preventDefault();navigate(a.dataset.route);return}let l=e.target.closest('[data-lang]');if(l){document.querySelectorAll('form[data-form="checkout"] [name]').forEach(x=>formDraft[x.name]=x.value);lang=l.dataset.lang;history.replaceState({},'',url(route)+location.search);render();return}let w=e.target.closest('[data-wish]');if(w){let id=w.dataset.wish;wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];render();toast(t(wish.includes(id)?'saved':'removed'));return}let s=e.target.closest('[data-size]');if(s){let id=s.dataset.product;variants[id]={...variants[id],size:+s.dataset.size};render();return}let add=e.target.closest('[data-add]');if(add){let id=add.dataset.add,v=variants[id]||{};if(!v.size){toast(t('chooseSize'));return}let qty=Math.max(1,Math.min(10,+document.getElementById('product-qty').value||1));let c=cart.find(c=>c.id===id&&c.size===v.size);if(c)c.qty=Math.min(10,c.qty+qty);else cart.push({id,size:v.size,qty});overlay='cart';render();toast(t('added'));return}let q=e.target.closest('[data-qty]');if(q){let i=+q.dataset.qty;cart[i].qty+=+q.dataset.delta;if(cart[i].qty<1)cart.splice(i,1);else cart[i].qty=Math.min(10,cart[i].qty);render();return}let rm=e.target.closest('[data-remove]');if(rm){cart.splice(+rm.dataset.remove,1);render();return}let f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;history.replaceState({},'',url(route)+(filter?'?category='+filter:''));render();return}let sl=e.target.closest('[data-slide]');if(sl){slide=+sl.dataset.slide;render();return}let thumb=e.target.closest('[data-thumb]');if(thumb){document.getElementById('main-product').src=asset(thumb.dataset.thumb);return}let gal=e.target.closest('[data-gallery]');if(gal){overlay='gallery:'+gal.dataset.gallery;renderOverlay();return}let action=e.target.closest('[data-action]')?.dataset.action;if(action==='reset'){filter='';query='';maxPrice=500;sort='best';history.replaceState({},'',url(route));render()}else if(action){overlay=action==='close'?'':action;renderOverlay()}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){let q=e.target.value.toLowerCase();let ps=products.filter(p=>name(p).toLowerCase().includes(q));document.getElementById('search-results').innerHTML=ps.length?grid(ps):`<p>${t('noResults')}</p>`}if(e.target.id==='catalog-search'){let pos=e.target.selectionStart;query=e.target.value;render();let el=document.getElementById('catalog-search');el.focus();el.setSelectionRange(pos,pos)}if(e.target.id==='product-qty'){let id=route.split('/')[2];variants[id]={...variants[id],qty:+e.target.value};save()}if(e.target.closest('form[data-form="checkout"]')&&e.target.name)formDraft[e.target.name]=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.id==='price'){maxPrice=+e.target.value;render()}});
document.addEventListener('submit',e=>{let f=e.target.dataset.form;if(!f)return;e.preventDefault();if(f==='newsletter'){localStorage.setItem('lm-newsletter-preference','true');toast(t('subscribed'))}else if(f==='checkout')toast(t('reviewed'));else toast(t('messageReady'))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay){overlay='';renderOverlay()}if(e.key==='Tab'&&overlay){let items=[...document.getElementById('overlay').querySelectorAll('button,a,input,select,textarea')].filter(x=>x.offsetParent!==null);if(!items.length)return;let first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
addEventListener('popstate',()=>{lang=/^\/(fr|en|ar)/.exec(location.pathname)?.[1]||'fr';route=location.pathname.replace(/^\/(fr|en|ar)/,'')||'/';filter=new URLSearchParams(location.search).get('category')||'';overlay='';render()});
if(!/^\/(fr|en|ar)(\/|$)/.test(location.pathname))history.replaceState({},'',url(route)+location.search);render();
